INSERT INTO projects (id,title,description,tech,thumbnail,screenshot,github,live,case_study,published,sort_order)
VALUES
('vyrdly','Vyrdly','AI-powered study group platform for real-time collaboration and session scheduling.',ARRAY['Node.js','PostgreSQL','BullMQ','Socket.io'],'/vyrdly-thumbnail.png','/vyrd.png','https://github.com/lakamo-samuel/StudyX.git','https://vyrdly.com/', '{"problem":"Students often rely on scattered chats and informal meetups to study together. That makes it difficult to find the right group, coordinate sessions, and keep useful material in one place.","approach":"Vyrdly brings study groups and their day-to-day work into one shared space. Members can discover or create groups, plan sessions, collaborate live, and keep resources connected to the group.","highlights":["Group discovery, invitations, and membership permissions","Scheduled sessions with attendance, agendas, and live chat","Shared resources with document viewing and AI summaries","Installable PWA with notifications and academic planning tools"],"outcome":"The result is a more organized study workflow that supports a group from finding collaborators through reviewing a session. The product is available at Vyrdly.com."}'::jsonb,true,1),
('iss','ISS: Interview Simulation System','AI-powered interview simulator with a credit-based economy and codebase deep-dives.',ARRAY['TypeScript','React','Node.js','Gemini'],'/iss-thumbnail.png','/iss-dark.png','https://github.com/lakamo-samuel/iss',NULL,'{"problem":"Interview practice can be difficult to structure, especially when candidates need to explain decisions in an unfamiliar codebase and get repeated practice.","approach":"ISS is an AI-powered interview simulator built around practice sessions and a credit-based economy. Its codebase deep-dives are intended to make technical discussion part of the interview preparation experience.","highlights":["AI-assisted interview practice","Credit-based access model","Codebase deep-dive sessions","React and TypeScript interface with a Gemini integration"],"outcome":"The project explores a focused way to rehearse technical interviews. Public project documentation is limited, so this case study is based on the portfolio description and listed technologies."}'::jsonb,true,2),
('chronovah','Chronovah','Personal dashboard for Notes and Journal with field-level encryption and offline-first sync.',ARRAY['React','TypeScript','Tailwind CSS','Dexie.js'],'/chronovah-thumbnail.png','/cronovah.png','https://github.com/lakamo-samuel/Chronovah','https://www.chronovah.xyz/','{"problem":"Notes and journal entries can contain personal information, while many writing tools assume a reliable connection and central online storage.","approach":"Chronovah is a personal notes and journal dashboard designed around field-level encryption and offline-first syncing, so writing can remain available when a connection is not.","highlights":["Notes and journal entries in one personal dashboard","Field-level encryption for sensitive content","Offline-first data handling with Dexie.js","React and TypeScript interface styled with Tailwind CSS"],"outcome":"The project combines private journaling with an offline-capable workflow. The public documentation available for this review is limited, so the description stays within the published project summary."}'::jsonb,true,3),
('atrixia','Atrixia','AI shopping assistant that researches products and explains its recommendations.',ARRAY['Gemma 4','TypeScript','PostgreSQL','SSE'],'/atrixia-thumbnail.png','/atrixia.png','https://github.com/lakamo-samuel/atrixia','https://atrixia.vercel.app/','{"problem":"Comparing products across marketplaces means jumping between listings, prices, seller details, and shipping information. It is hard to weigh those tradeoffs against what a shopper actually wants.","approach":"Atrixia turns a natural-language shopping request into constraints, gathers listings through marketplace adapters, then normalizes and compares the results. Its AI produces a decision report with reasoning, tradeoffs, alternatives, and confidence.","highlights":["Natural-language shopping requests and saved preferences","Marketplace adapters with normalized, deduplicated results","Recommendations that explain tradeoffs and alternatives","Gemma 4, PostgreSQL, and streaming responses via SSE"],"outcome":"Atrixia makes product research easier to review by showing why an option fits and what compromises it brings. Image-based search is not described as a completed feature in the available project documentation."}'::jsonb,true,4)
